// Package transport provides predefined transport protocol.
package transport

import "strings"

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	PurePayload Protocol = 0

	TTHeader Protocol = 1 << iota // 2
	Framed                         // 4
	HTTP                           // 8
	GRPC                           // 16
	HESSIAN2                       // 32
	TTHeaderStreaming              // 64 (dedicated flag)
	GRPCStreaming                  // 128 (dedicated flag)

	TTHeaderFramed = TTHeader | Framed // composite
)

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
func (tp Protocol) String() string {
	if tp == 0 {
		return "PurePayload"
	}

	// Check for known individual flags first
	switch tp {
	case TTHeader:
		return "TTHeader"
	case Framed:
		return "Framed"
	case HTTP:
		return "HTTP"
	case GRPC:
		return "GRPC"
	case HESSIAN2:
		return "Hessian2"
	case TTHeaderStreaming:
		return "TTHeaderStreaming"
	case GRPCStreaming:
		return "GRPCStreaming"
	case TTHeaderFramed:
		return "TTHeaderFramed"
	}

